DROP TABLE IF EXISTS `msbatch`;
CREATE TABLE `msbatch` (
  `batchcode` char(10) NOT NULL,
  `description` char(50) NOT NULL,
  `batchstatus` enum('0','1') NOT NULL DEFAULT '1',
  `updateby` varchar(45) NOT NULL,
  `updatetime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `createby` varchar(45) NOT NULL,
  `createtime` datetime NOT NULL,
  PRIMARY KEY (`batchcode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;


DROP TABLE IF EXISTS `mscompany`;
CREATE TABLE `mscompany` (
  `compcode` char(4) NOT NULL,
  `descode1` varchar(64) NOT NULL,
  `compname` char(50) NOT NULL,
  `wilcode` char(4) NOT NULL,
  `compaddr` char(200) NOT NULL,
  `compaddr2` char(200) NOT NULL,
